begin;
select plan(17);
select ok(to_regprocedure('platform.list_my_customer_contexts()') is not null,'context list RPC exists');
select ok(to_regprocedure('platform.get_customer_dashboard(uuid)') is not null,'dashboard RPC exists');
select ok(to_regprocedure('app_private.customer_context_is_active(uuid)') is not null,'context predicate exists');
select ok(has_function_privilege('authenticated','platform.list_my_customer_contexts()','EXECUTE'),'authenticated may list own contexts');
select ok(not has_function_privilege('anon','platform.list_my_customer_contexts()','EXECUTE'),'anon cannot list contexts');
select ok(has_function_privilege('authenticated','platform.get_customer_dashboard(uuid)','EXECUTE'),'authenticated may request dashboard');
select ok(not has_function_privilege('anon','platform.get_customer_dashboard(uuid)','EXECUTE'),'anon cannot request dashboard');
do $$ begin
 insert into auth.users(id,email) values('18000000-0000-0000-0000-000000000001','customer-018@cladora.test'),('18000000-0000-0000-0000-000000000002','other-018@cladora.test');
 insert into platform.tenants(id,legal_name,registration_number,status) values('18100000-0000-0000-0000-000000000001','Tenant One','ENG018-1','active'),('18100000-0000-0000-0000-000000000002','Tenant Two','ENG018-2','active');
 insert into identity.roles(id,tenant_id,code,name) values('18200000-0000-0000-0000-000000000001','18100000-0000-0000-0000-000000000001','association_admin','Association administrator'),('18200000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000002','association_admin','Other administrator');
 insert into identity.memberships(id,tenant_id,user_id,role_id,status,starts_at) values('18300000-0000-0000-0000-000000000001','18100000-0000-0000-0000-000000000001','18000000-0000-0000-0000-000000000001','18200000-0000-0000-0000-000000000001','active',statement_timestamp()-interval '1 day'),('18300000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000002','18000000-0000-0000-0000-000000000002','18200000-0000-0000-0000-000000000002','active',statement_timestamp()-interval '1 day');
 insert into identity.context_grants(id,membership_id,tenant_id,scope_type,starts_at) values('18400000-0000-0000-0000-000000000001','18300000-0000-0000-0000-000000000001','18100000-0000-0000-0000-000000000001','tenant',statement_timestamp()-interval '1 day'),('18400000-0000-0000-0000-000000000002','18300000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000002','tenant',statement_timestamp()-interval '1 day');
 insert into identity.context_grants(id,membership_id,tenant_id,scope_type,starts_at,ends_at) values('18400000-0000-0000-0000-000000000003','18300000-0000-0000-0000-000000000001','18100000-0000-0000-0000-000000000001','tenant',statement_timestamp()-interval '2 day',statement_timestamp()-interval '1 day');
 insert into portfolio.properties(id,tenant_id,type,name,status) values('18500000-0000-0000-0000-000000000001','18100000-0000-0000-0000-000000000001','condominium','One Property','active'),('18500000-0000-0000-0000-000000000002','18100000-0000-0000-0000-000000000002','condominium','Other Property','active');
 insert into platform.customer_workspaces(id,tenant_id,workspace_type,lifecycle_status,commercial_owner,environment) values('18800000-0000-0000-0000-000000000001','18100000-0000-0000-0000-000000000001','ASSOCIATION','ACTIVE','Commercial 018','PILOT');
end $$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"18000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal2"}',true);
select ok((select count(*) from platform.list_my_customer_contexts())=1,'only active actor context is listed');
select ok((select tenant_id='18100000-0000-0000-0000-000000000001' from platform.list_my_customer_contexts()),'listed context belongs to actor tenant');
select ok(app_private.customer_context_is_active('18400000-0000-0000-0000-000000000001'),'active context is accepted');
select ok(not app_private.customer_context_is_active('18400000-0000-0000-0000-000000000002'),'cross-tenant context is rejected');
select ok(not app_private.customer_context_is_active('18400000-0000-0000-0000-000000000003'),'expired context is rejected');
select ok((platform.get_customer_dashboard('18400000-0000-0000-0000-000000000001')#>>'{kpis,properties}')::int=1,'dashboard scope contains own property');
select ok(platform.get_customer_dashboard('18400000-0000-0000-0000-000000000001')#>>'{context,tenant_id}'='18100000-0000-0000-0000-000000000001','dashboard identifies validated tenant');
select throws_like($$select platform.get_customer_dashboard('18400000-0000-0000-0000-000000000002')$$,'%customer_context_access_denied%','cross-tenant dashboard fails closed');
select set_config('request.jwt.claims','{"sub":"18000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1"}',true);
select throws_like($$select * from platform.list_my_customer_contexts()$$,'%mfa_required%','AAL1 cannot list contexts');
select throws_like($$select platform.get_customer_dashboard('18400000-0000-0000-0000-000000000001')$$,'%mfa_required%','AAL1 cannot load dashboard');
select * from finish();
rollback;
